import random, subprocess, sys
# build escaped-codepoint set from sweeps (executable-observed only)
esc=set()
for f,base in (('bmp.txt',0),('astral.txt',0)):
    line=open('/tmp/reprarea/'+f).read().strip().split('\n')[-1]
    for tok in line.split():
        if '-' in tok:
            a,b=tok.split('-'); esc.update(range(int(a,16),int(b,16)+1))
        else: esc.add(int(tok,16))
esc.update(range(0x00,0x20)); esc.update(range(0xD800,0xE000))  # C0 controls + surrogates
SPECIAL={0x09:'\\t',0x0a:'\\n',0x0d:'\\r'}
def myrepr(s):
    q="'"
    if "'" in s and '"' not in s: q='"'
    out=[q]
    for ch in s:
        c=ord(ch)
        if ch==q or ch=='\\': out.append('\\'+ch)
        elif c in SPECIAL: out.append(SPECIAL[c])
        elif c in esc:
            if c<0x100: out.append('\\x%02x'%c)
            elif c<0x10000: out.append('\\u%04x'%c)
            else: out.append('\\U%08x'%c)
        else: out.append(ch)
    out.append(q)
    return ''.join(out)
random.seed(7)
pool=[0x27,0x22,0x5c,0x09,0x0a,0x0d,0x0b,0x0c,0x07,0x1b,0x7f,0x20,0x41,0xa0,0xad,0xe9,0x301,0x378,0x200b,0x2028,0x3000,0xe000,0xffff,0x1f600,0x10ffff,0xe0001,0x1d173,0x0301,0x1,0x1f,0x80,0x9f,0x2060,0xfdd0,0x2ffc,0x11f00]
bad=0
for t in range(45):
    n=random.randint(1,25)
    s=''.join(chr(random.choice(pool)) for _ in range(n))
    if '\x00' in s: continue
    r=subprocess.run(['/workspace/dataset/test15_executable','--a',s,'--b','1','--c','2'],capture_output=True)
    got=r.stdout.decode('utf-8').split('\n')[2]
    want="{'x': "+myrepr(s)+", 'y': 2}"
    if got!=want:
        bad+=1; print("MISMATCH t=%d"%t); print(" got :",got); print(" want:",want)
print("tested 45, mismatches=",bad)
